mod rows_characterization_tests {
    use super::*;

    fn bits(v: &[f64]) -> Vec<u64> {
        v.iter().map(|x| x.to_bits()).collect()
    }

    #[test]
    fn system_edge_and_pair_rows_match_characterized_construction() {
        let points = vec![[0.0, 0.0], [4.0, 0.0], [4.0, 3.0], [0.0, 3.0]];
        let mut system = System::new(points, 10.0);
        system.edge(0, 1).expect("axis edge must build");
        system.edge(1, 0).expect("axis edge must build");
        let groups: Vec<u8> = system
            .rows
            .iter()
            .map(|(g, _, _)| match g {
                RowGroup::Position => 0,
                RowGroup::Stretch => 1,
                RowGroup::Bend => 2,
                RowGroup::InkMatch => 3,
            })
            .collect();
            let result = solve_hard(&soft, &hard, &HashMap::new(), 1).unwrap();
            assert!((result[0] - 2.5).abs() < 1e-9);
            assert!((result[1] - 3.5).abs() < 1e-9);
        }
    }

    #[test]
    fn redundant_hard_rows_preserve_unconstrained_coordinates() {
        let soft: Vec<_> = (0..4)
            .map(|i| {
                let mut row = vec![0.0; 4];
                row[i] = 1.0;
                (RowGroup::Position, row, -((i + 1) as f64))
            })
            .collect();
        let hard = vec![
            (vec![1.0, -1.0, 0.0, 0.0], 0.0),
            (vec![2.0, -2.0, 0.0, 0.0], 0.0),
            (vec![0.0; 4], 0.0),
        ];
        let result = solve_hard(&soft, &hard, &HashMap::new(), 2).unwrap();
        for (got, want) in result.iter().zip([1.5, 1.5, 3.0, 4.0]) {
            assert!((got - want).abs() < 1e-9);
        }
    }
}

