    /// Hobby (1)-(3), with directions/lengths from input geometry.
    fn edge(&mut self, i: usize, j: usize) -> Result<(), ()> {
        let built = super::rows::edge_rows(&self.points, self.height, i, j, |a, dir, b| {
            self.projected(a, dir, b)
        })?;
        self.rows.push((0, built.sum, 0.0));
        self.rows.push((0, built.diff, 0.0));
        self.rows.push((GROUP_STRETCH, built.stretch, 0.0));
        self.rows.push((GROUP_BEND, built.bend, 0.0));
