    /// Hobby (1)-(3), with directions/lengths from input geometry.
    fn edge(&mut self, i: usize, j: usize) -> Result<(), ()> {
        let built = super::rows::edge_rows(&self.points, self.height, i, j, |a, dir, b| {
            self.projected(a, dir, b)
        })?;
        self.rows.push((0, built.sum, 0.0));
        self.rows.push((0, built.diff, 0.0));
        self.rows.push((GROUP_STRETCH, built.stretch, 0.0));
        self.rows.push((GROUP_BEND, built.bend, 0.0));
        Ok(())
    }

    /// Hobby (4),(5): input contacts, medial point and arc-length weight.
    fn pair(
        &self,
        a: &Sample,
        b: &Sample,
        arc: f64,
        medial: [f64; 2],
    ) -> Result<(Vec<f64>, f64, [f64; 2]), ()> {
        super::rows::pair_residual(&self.points, a, b, arc, medial, |a, dir, b| {
            self.projected(a, dir, b)
        })
    }

    /// Quadratic form of the Hobby (31)-(33) + (2),(3) construction.
    ///
    /// Quadratic Bernstein weights and derivative weights
    /// `(-2(1-t), 2(1-t)-2t, 2t)` with 16 midpoint intervals; same group
    /// names feed the same upstream-gap constant substitution.
    fn quad_shape(&mut self, ctrl: [usize; 3]) {
        let get = |v: usize| self.points[v];
        let controls = [get(ctrl[0]), get(ctrl[1]), get(ctrl[2])];
        let intervals = 16;
        for j in 0..intervals {
            let t = (f64::from(j) + 0.5) / f64::from(intervals);
            let basis = [(1.0 - t).powi(2), 2.0 * t * (1.0 - t), t * t];
            let deriv_w = [-2.0 * (1.0 - t), 2.0 * (1.0 - t) - 2.0 * t, 2.0 * t];
            let mut deriv = [0.0, 0.0];
            for (w, c) in deriv_w.iter().zip(controls.iter()) {
                deriv[0] += w * c[0];
                deriv[1] += w * c[1];
            }
            let speed = norm(deriv);
            if !(speed > 0.0) {
                continue;
            }
            let normal = [deriv[1] / speed, -deriv[0] / speed];
            let tangent = [deriv[0] / speed, deriv[1] / speed];
    }
}

/// Minimum-norm least squares via SVD, NumPy `lstsq(rcond=None)` semantics.
///
/// Rank rule matches the prototype exactly: singular values above
/// `eps * max(m, n) * sigma_max` are kept (`eps` is machine epsilon);
/// the solution is the minimum-norm one in the free modes. No regularizer,
/// no rank-loss rejection: rank deficiency still solves.
fn min_norm_solve(
    a: &nalgebra::DMatrix<f64>,
    b: &nalgebra::DVector<f64>,
) -> nalgebra::DVector<f64> {
    let (m, n) = (a.nrows(), a.ncols());
    if m == 0 || n == 0 {
        return nalgebra::DVector::zeros(n);
    }
    let svd = a.clone().svd(true, true);
    let sigmax = svd.singular_values.iter().cloned().fold(0.0_f64, f64::max);
    if !(sigmax > 0.0) {
        return nalgebra::DVector::zeros(n);
    }
    let tol = f64::EPSILON * (m.max(n) as f64) * sigmax;
    let (Some(u), Some(vt)) = (svd.u, svd.v_t) else {
        return nalgebra::DVector::zeros(n);
    };
    let utb: nalgebra::DVector<f64> = u.transpose() * b;
    let mut x = nalgebra::DVector::zeros(n);
    for (i, &s) in svd.singular_values.iter().enumerate() {
        if s > tol {
            let c = utb[i] / s;
            for j in 0..n {
                x[j] += vt[(i, j)] * c;
            }
        }
    }
    x
}

