    entries = _load_entries(args)
    cases, ids = [], set()
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) - (set(defaults) | {'id', 'size_px'}):
            raise ValueError('Case contains unknown settings')
        case = {**defaults, **entry}
