        _resolve_case_font(case, args.config)
        _validate_case(case)
        resolve_renderer_policy(case)
        cases.append(case)
    if args.publish and len(cases) != 1:
        raise ValueError('--publish requires exactly one case')
    return cases


def main():
    args = arguments()

